-- 004-compliance-reports-org-id-column.sql — collector VOLT database (volt.db)
--
-- Adds org_id to compliance_reports so the PostureDashboard's overallScore
-- (useComplianceData -> GET /compliance/reports) reflects the CALLER's org
-- instead of every tenant's reports globally — previously this table had no
-- org_id at all, so any authenticated caller saw a blended/global score that
-- disagreed with the already org-scoped Monitor tab (GET
-- /api/v1/compliance/monitor/posture, AEE-ORG-1).
--
-- Nullable — reports generated by the background compliance_jobs scheduler
-- (server-side cron, no caller/HTTP request context) legitimately have no
-- org and must NOT have one fabricated. Precedent: 002-envelopes-org-id-column.sql
-- (aee.db), 003-volt-runs-org-id-column.sql (volt.db).
--
-- SQLite has no "ADD COLUMN IF NOT EXISTS" — on an already-migrated DB this
-- throws "duplicate column name", which runMigrations.js tolerates as a
-- no-op (see TOLERATED_ERROR in lib/runMigrations.js).

ALTER TABLE compliance_reports ADD COLUMN org_id TEXT;
CREATE INDEX IF NOT EXISTS idx_compliance_reports_org ON compliance_reports(org_id);
